import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, Color } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  // Root object
  const root = new ctx.THREE.Group();

  // Backdrop plane with vertical gradient (ink → surface)
  const planeGeom = new ctx.THREE.PlaneGeometry(7, 6);
  const surfaceCol = new Color('#0b0b10');
  const inkCol = new Color('#16161d');

  const gradientMat = new MeshStandardNodeMaterial();
  gradientMat.colorNode = mix(
    vec3(surfaceCol.r, surfaceCol.g, surfaceCol.b),
    vec3(inkCol.r, inkCol.g, inkCol.b),
    uv().y
  );
  gradientMat.metalness = 0;
  gradientMat.roughness = 1;
  const backdrop = new ctx.THREE.Mesh(planeGeom, gradientMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // Placeholder for GLB mesh
  const meshHolder = new ctx.THREE.Group();
  root.add(meshHolder);
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      meshHolder.add(gltf.scene);
    });
  }

  // Apply cinematic primitives
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const inst = ctx.primitives[prim.name](root, prim.params);
      primitiveInstances.push(inst);
    }
  }

  // Event handlers container
  root.userData.handlers = {};

  // Hover rise‑in effect (0.15 units upward)
  root.userData.handlers.hover = () => {
    const tl = gsap.timeline();
    tl.to(root.position, {
      y: root.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    root.userData._hoverTimeline = tl;
  };

  // Click navigation emit
  root.userData.handlers.click = () => {
    ctx.emit('navigate', { to: 'hub-collection' });
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose backdrop resources
    gradientMat.dispose();
    planeGeom.dispose();

    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst.cleanup) inst.cleanup();
    }

    // Kill GSAP timelines
    if (root.userData._hoverTimeline) {
      root.userData._hoverTimeline.kill();
    }
  };

  return root;
}
